      "description_uz": "Samarqand, Buxoro va Xiva kabi qadimiy shaharlarni o'z ichiga olgan O'zbekiston bo'ylab eng uzun va unutilmas madaniy-tabiat sayohati. Dastur nafaqat tarixiy obidalarni, balki tuya minish safari, Nurotadagi milliy o'tovlarda yashash, gulxan atrofidagi unutilmas oqshomlar, Marg'ilondagi ipak fabrikasi va Rishton kulolchilik ustaxonalarini ham o'z ichiga oladi.",
      "route_it": "Tashkent - Samarcanda - Nurota - Bukhara - Khiva - Tashkent - Fergana - Tashkent",
      "route_en": "Tashkent - Samarkand - Nurata - Bukhara - Khiva - Tashkent - Fergana - Tashkent",
      "route_uz": "Tashkent - Samarkand - Nurota - Bukhara - Khiva - Tashkent - Fergana - Tashkent",
      "paymentInfo_it": "Pagamenti in valuta locale al tasso di cambio ufficiale. Gruppi oltre i 10 negoziabili.",
      "paymentInfo_en": "Payments via local currency at official exchange rate. Groups over 10 negotiable.",
      "paymentInfo_uz": "O'zbekiston rezidentlari uchun to'lov to'lov kunidagi davlat kursi bo'yicha milliy valyutada (so'mda) amalga oshiriladi. 10 kishidan ortiq guruhlar uchun narxlar so'rov bo'yicha kelishiladi.",
      "included_it": "Alloggio, Campo di iurte (3 pasti), Giro in cammello, Fabbrica di seta, Laboratorio di ceramica, Guida, Volo interno, Biglietti",
      "included_en": "Accommodation, Yurt camp (3 meals), Camel ride, Silk factory, Pottery workshop, Guide, Domestic flight, Tickets",
      "included_uz": "Mehmonxonalarda joylashish, Milliy o'tov lagerida yashash (3 mahal ovqat bilan), Tuya minish safari, Marg'ilondagi Yodgorlik ipak fabrikasiga tashrif, Rishtondagi kulolchilik ustaxonasiga tashrif, Professional gid xizmatlari, Urganch - Toshkent ichki aviareysi chiptasi, Obidalarga kirish chiptalari",
      "notIncluded_it": "Voli internazionali, Pasti non specificati, Assicurazione, Tariffe foto, Spese personali, Mance",
      "notIncluded_en": "International flights, Unspecified meals, Insurance, Photo fees, Personal expenses, Tips",
      "notIncluded_uz": "Xalqaro aviachiptalar, Toshkent - Urgench reysi (agar qo'shimcha bo'lsa), Dasturdan tashqari ovqatlanishlar, Tibbiy sug'urta, Foto va video suratga olish to'lovlari, Shaxsiy xarajatlar, Gid va haydovchilarga choychaqa"
