      "desc": "O'zbekcha xonim - bug'da pishiriladigan, xamir ichiga mayda somoncha qilib to'g'ralgan kartoshka yoki go'shtli qiyma solib, rulet shaklida o'raladigan o'ziga xos to'yimli taomdir. Xonim o'zining tayyorlanishi qulayligi va arzonligi sababli o'zbek oilalarida juda mashhur. Yupqa yoyilgan xamirga o'simlik yog'i surtiladi, ustiga tuzlangan kartoshka va piyoz aralashmasi bir tekisda yoyilib, mahkam o'raladi. Mantiqasqonda 40 daqiqa davomida bug'da pishiriladi. Xonimning ustiga pomidor va piyozdan qovurib tayyorlangan issiq qayla (sous) quyiladi va yashil ko'katlar bilan bezatiladi.",
